
-- Handbook v1.14 remediation: turn generic messages into distinct, non-authorizing business mail.
WITH facts AS (
  SELECT rowid AS rid,
    CASE uid % 17
      WHEN 0 THEN 'MBA English textalreadyEnglish text' WHEN 1 THEN 'programscheduleEnglish text' WHEN 2 THEN 'English textsessionEnglish text'
      WHEN 3 THEN 'countEnglish textalreadyEnglish text' WHEN 4 THEN 'No.English textpleasedescriptionEnglish textasEnglish text' WHEN 5 THEN 'officialnewEnglish text'
      WHEN 6 THEN 'clientEnglish textpendingEnglish text' WHEN 7 THEN 'English textpreparationchecklist' WHEN 8 THEN 'English textwillEnglish text'
      WHEN 9 THEN 'English textpolicyupdateEnglish text' WHEN 10 THEN 'English textalreadyEnglish text' WHEN 11 THEN 'English textstudyEnglish text'
      WHEN 12 THEN 'English textsessiontime' WHEN 13 THEN 'English textreminderEnglish text' WHEN 14 THEN 'English textpleaseEnglish text'
      WHEN 15 THEN 'dayEnglish texttime zoneEnglish textchange' ELSE 'English textworkshopEnglish text' END AS subject_fact,
    CASE uid % 19
      WHEN 0 THEN 'English textinformationEnglish text，notEnglish textregistration confirmation' WHEN 1 THEN 'needatEnglish text' WHEN 2 THEN 'English texthaspaymentorEnglish textauthorization'
      WHEN 3 THEN 'canatEnglish text' WHEN 4 THEN 'andexamEnglish textnoneEnglish text' WHEN 5 THEN 'English textprogram，notEnglish textexternal sharing'
      WHEN 6 THEN 'English text' WHEN 7 THEN 'English textconfirmedtime' WHEN 8 THEN 'historicalversionEnglish textretainEnglish text'
      WHEN 9 THEN 'English textinofdayEnglish textuseofficialportalas authority' WHEN 10 THEN 'notcanEnglish textscorestatus' WHEN 11 THEN 'notEnglish textapplication submissionEnglish text'
      WHEN 12 THEN 'English textenteredbudget' WHEN 13 THEN 'firstandworkdayEnglish textcheckEnglish text' WHEN 14 THEN 'noneEnglish text'
      WHEN 15 THEN 'onlyrecordEnglish textinformation' WHEN 16 THEN 'English texthasEnglish textcopyEnglish text' WHEN 17 THEN 'subsequentmayhasEnglish textemail'
      ELSE 'English textafterEnglish textasalreadyEnglish textcan' END AS handling_fact
  FROM messages WHERE message_id LIKE '<mail_noise_examprep_%'
)
UPDATE messages
SET subject = (SELECT subject_fact FROM facts WHERE facts.rid=messages.rowid),
    body_text = CASE uid % 7
      WHEN 0 THEN (SELECT subject_fact || '。English text：' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
      WHEN 1 THEN (SELECT 'English textupdate：' || subject_fact || '；' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
      WHEN 2 THEN (SELECT handling_fact || '。emailbodyrecordofEnglish textas“' || subject_fact || '”。' FROM facts WHERE facts.rid=messages.rowid)
      WHEN 3 THEN (SELECT 'English textemailEnglish textonEnglish text' || subject_fact || '。English textstatusdescription：' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
      WHEN 4 THEN (SELECT 'English text——' || subject_fact || '；English textpleaseEnglish text：' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
      WHEN 5 THEN (SELECT subject_fact || '，English textonEnglish text；' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
      ELSE (SELECT 'thisEnglish textdescription' || subject_fact || '。subsequentrulesis' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
    END,
    message_id = replace(message_id, 'mail_noise_examprep_', 'mail_context_examprep_')
WHERE message_id LIKE '<mail_noise_examprep_%';
